#[tokio::test]
async fn the_generated_deny_all_default_refuses_every_page() -> TestResult {
    let harness = Harness::new(Arc::new(DenyAll))?;
    let id = EventId::new();
    let member = format!("{}/{id}", harness.collection);

    for path in [
        harness.collection.clone(),
        format!("{}/new", harness.collection),
        member.clone(),
        format!("{member}/edit"),
    ] {
        assert_eq!(
            harness.get(&path).await?.status(),
            StatusCode::FORBIDDEN,
            "{path}"
        );
    }

    // CSRF protection is a double-submit check, so any well-formed token in
    // both the cookie and the form passes it: the allowing router accepts
    // this one, and the 403s below therefore come from DenyAll.
    let token = "ab".repeat(32);
    let allowing = Harness::allowing()?;
    let accepted = allowing.submit(&allowing.collection, &token, VALID).await?;
    assert_eq!(accepted.status(), StatusCode::SEE_OTHER);
    let edit = format!("{VALID}&_method=patch&version=1");
    for (path, form) in [
        (harness.collection.as_str(), VALID),
        (member.as_str(), edit.as_str()),
        (member.as_str(), "_method=put&version=1"),
        (member.as_str(), "_method=delete&version=1"),
    ] {
        let refused = harness.submit(path, &token, form).await?;
        assert_eq!(refused.status(), StatusCode::FORBIDDEN, "{path} {form}");
        assert!(set_cookie(&refused, "__Host-forge_flash").is_none());
    }
    Ok(())
}

/// Browsers blank a `datetime-local` value with more than three fractional
/// digits, so forms render whole seconds and refuse anything finer: editing
/// a record never loses or changes a timestamp silently.
#[tokio::test]
async fn sub_second_timestamps_are_refused_and_edit_forms_show_whole_seconds() -> TestResult {
    let harness = Harness::allowing()?;
    let token = harness.csrf_token().await?;

    let refused = harness
        .submit(&harness.collection, &token, SUBSECOND)
        .await?;
    assert_eq!(refused.status(), StatusCode::UNPROCESSABLE_ENTITY);
    assert!(body(&refused)?.contains("whole seconds"));

    let stored = Event::new(attributes()?)?;
    let context = member_context(harness.tenant, &Permission::new(WRITE_PERMISSION)?)?;
    harness.repository.insert(&context, &stored).await?;
    let edit = harness
        .get(&format!("{}/{}/edit", harness.collection, stored.id()))
        .await?;
    let page = body(&edit)?;
    assert_eq!(edit.status(), StatusCode::OK);
    assert!(page.contains("value=\"2026-01-02T03:04:05\""), "{page}");
    assert!(!page.contains(".123456"), "{page}");
    Ok(())
}

/// The HTTP layer asks `events:read` for the index and show pages; the
/// use cases agree: listing needs the read grant, loading one event also
/// accepts the write grant (edit and update load the event they change),
/// and changes need the write grant.
#[tokio::test]
async fn use_cases_check_the_grant_of_the_tenant_context() -> TestResult {
    let service = EventService::new(Arc::new(InMemoryEvents::default()));
    let tenant = TenantId::new();
    let writer = member_context(tenant, &Permission::new(WRITE_PERMISSION)?)?;
    let reader = member_context(tenant, &Permission::new(READ_PERMISSION)?)?;

    let created = service.create(&writer, attributes()?).await?;

    assert!(matches!(
        service.list(&writer, None).await,
        Err(EventError::Forbidden)
    ));
    assert_eq!(service.list(&reader, None).await?.events.len(), 1);
    assert_eq!(
        service.find(&reader, created.id()).await?.id(),
        created.id()
    );
    assert_eq!(
        service.find(&writer, created.id()).await?.id(),
        created.id()
    );
    assert!(matches!(
        service.create(&reader, attributes()?).await,
        Err(EventError::Forbidden)
    ));
    assert!(matches!(
        service
            .delete(&reader, created.id(), created.version())
            .await,
        Err(EventError::Forbidden)
    ));
    Ok(())
}

impl Harness {
    /// The channel of the event pages.
    fn channel(&self) -> Result<Channel, Box<dyn Error>> {
        Ok(Channel::for_tenant(self.tenant, "events")?)
    }
}

/// The URL of the `<turbo-stream-source>` a page renders.
fn stream_source(page: &str) -> Result<String, Box<dyn Error>> {
    const OPEN: &str = "<turbo-stream-source src=\"";
    let start = page.find(OPEN).ok_or("the page subscribes")? + OPEN.len();
    let end = start + page[start..].find('"').ok_or("the attribute is closed")?;
    Ok(page[start..end].replace("&amp;", "&"))
}

/// The next chunk of an event stream (published before it is read).
async fn next_event(stream: &mut Response) -> Result<String, Box<dyn Error>> {
    let chunk = stream.next_chunk().await.ok_or("the stream ended")?;
    Ok(String::from_utf8(chunk.to_vec())?)
}

/// `--broadcast`: the index subscribes, and create, update and delete reach
/// the open stream as Turbo Streams with nothing specific to the person who
/// made the change.
#[tokio::test]
async fn changes_are_broadcast_to_open_lists() -> TestResult {
    let harness = Harness::allowing()?;
    let token = harness.csrf_token().await?;
    let index = body(&harness.get(&harness.collection).await?)?;
    let source = stream_source(&index)?;
    let streams_path = format!("/tenants/{}/streams?stream=", harness.tenant);
    assert!(source.starts_with(&streams_path), "{source}");
    assert!(index.contains("<tr id=\"events_empty\">"), "{index}");

    let mut stream = harness.get(&source).await?;
    assert_eq!(stream.status(), StatusCode::OK);
    assert_eq!(
        stream
            .headers()
            .get(header::CONTENT_TYPE)
            .map(HeaderValue::as_bytes),
        Some(&b"text/event-stream; charset=utf-8"[..])
    );
    assert_eq!(
        next_event(&mut stream).await?,
        "retry: 3000\n: connected\n\n"
    );

    let member = harness.create(&token).await?;
    let id = member.rsplit('/').next().ok_or("an id")?.to_owned();
    let created = next_event(&mut stream).await?;
    assert!(
        created.contains(
            "data: <turbo-stream action=\"remove\" target=\"events_empty\"></turbo-stream>"
        ),
        "{created}"
    );
    assert!(
        created.contains(&format!(
            "data: <turbo-stream action=\"append\" target=\"events\"><template><tr id=\"event_{id}\">"
        )),
        "{created}"
    );
    assert!(created.contains(&member), "{created}");
    assert!(
        !created.contains(&token) && !created.contains("csrf"),
        "{created}"
    );
    let index = body(&harness.get(&harness.collection).await?)?;
    assert!(
        index.contains(&format!("<tr id=\"event_{id}\">")),
        "{index}"
    );

    let updated = harness
        .submit(&member, &token, &format!("{VALID}&_method=patch&version=1"))
        .await?;
    assert_eq!(updated.status(), StatusCode::SEE_OTHER);
    let replaced = next_event(&mut stream).await?;
    assert!(
        replaced.starts_with(&format!(
            "data: <turbo-stream action=\"replace\" target=\"event_{id}\"><template>"
        )),
        "{replaced}"
    );

    let deleted = harness
        .submit(&member, &token, "_method=delete&version=2")
        .await?;
    assert_eq!(deleted.status(), StatusCode::SEE_OTHER);
    assert_eq!(
        next_event(&mut stream).await?,
        format!(
            "data: <turbo-stream action=\"remove\" target=\"event_{id}\"></turbo-stream>\ndata: \n\n"
        )
    );
    Ok(())
}

/// Streams fail closed: a forged token, a channel no resource registered and
/// a caller the access policy refuses get `403`, and nothing is subscribed.
#[tokio::test]
async fn streams_refuse_forged_unknown_and_unauthorized_subscriptions() -> TestResult {
    let harness = Harness::allowing()?;
    let source = stream_source(&harness.streams.source(&harness.channel()?).ok_or("signs")?)?;
    let path = source
        .split_once('?')
        .map(|(path, _)| path.to_owned())
        .ok_or("a stream URL")?;
    let unknown = stream_source(
        &harness
            .streams
            .source(&Channel::global("unregistered")?)
            .ok_or("signs")?,
    )?;

    for uri in [format!("{path}?stream=forged"), path.clone(), unknown] {
        let refused = harness.get(&uri).await?;
        assert_eq!(refused.status(), StatusCode::FORBIDDEN, "{uri}");
    }

    let denied = Harness::new(Arc::new(DenyAll))?;
    let denied_source = stream_source(&denied.streams.source(&denied.channel()?).ok_or("signs")?)?;
    assert_eq!(
        denied.get(&denied_source).await?.status(),
        StatusCode::FORBIDDEN
    );
    Ok(())
}

/// A tenant's stream never reaches another tenant: its token presented under
/// another tenant's path (where that tenant's member is authorized) is
/// refused, and another tenant's channel hears nothing of the change.
#[tokio::test]
async fn broadcasts_stay_in_their_tenant() -> TestResult {
    let harness = Harness::allowing()?;
    let token = harness.csrf_token().await?;
    let source = stream_source(&body(&harness.get(&harness.collection).await?)?)?;
    let other = TenantId::new();
    let elsewhere = source.replace(&harness.tenant.to_string(), &other.to_string());
    assert_ne!(elsewhere, source);

    let refused = harness.get(&elsewhere).await?;
    assert_eq!(refused.status(), StatusCode::FORBIDDEN);

    let mut other_list = harness
        .streams
        .broker()
        .subscribe(&Channel::for_tenant(other, "events")?)?;
    let mut own_list = harness.streams.broker().subscribe(&harness.channel()?)?;
    harness.create(&token).await?;
    assert!(
        own_list.next().await.is_ok(),
        "the tenant's own list hears it"
    );
    let quiet = tokio::select! {
        biased;
        received = other_list.next() => received.is_err(),
        () = std::future::ready(()) => true,
    };
    assert!(quiet, "another tenant's list hears nothing");
    Ok(())
}
